  "about.founderHeading": "📖 ಸ್ಥಾಪಕರ ಬಗ್ಗೆ",
  "about.founder.p1": "ಹಲೋ, ನಾನು ಕಾನ್ಸೆಪ್ಸಿಯೋನ್, Luminous StockHaven ನ ಸ್ಥಾಪಕಿ.",
  "about.founder.p2": "ನಾನು ದೊಡ್ಡ ಟೆಕ್ ಕಂಪನಿಯಿಂದ ಬಂದವಳಲ್ಲ, ನಾನು ಕಾರ್ಪೊರೇಟ್ ಕಚೇರಿಯಲ್ಲಿ ಕುಳಿತುಕೊಳ್ಳುವುದಿಲ್ಲ. ನಾನು ನಿಮ್ಮಂತೆಯೇ ಒಬ್ಬ ಸಣ್ಣ ಚಿಲ್ಲರೆ ವ್ಯಾಪಾರಿ. ಪುಸ್ತಕಗಳು ಮತ್ತು ಪುಸ್ತಕ ಪ್ರೇಮಿಗಳಿಗಾಗಿ ಕೈಯಿಂದ ಮಾಡಿದ ಪರಿಕರಗಳಲ್ಲಿ ಪರಿಣತಿ ಹೊಂದಿರುವ ಐದು ಇ-ಕಾಮರ್ಸ್ ಅಂಗಡಿಗಳನ್ನು ನಾನು ನಿರ್ವಹಿಸುತ್ತೇನೆ.\nಅನೇಕ ಸ್ವತಂತ್ರ ಚಿಲ್ಲರೆ ವ್ಯಾಪಾರಿಗಳಂತೆ, ಹಲವು ಸ್ಥಳಗಳ ದಾಸ್ತಾನನ್ನು ನಿರ್ವಹಿಸಲು, ಪ್ರಕಾಶಕರ ISBN ಗಳನ್ನು ನನ್ನ ಸ್ವಂತ ಕೈಯಿಂದ ಮಾಡಿದ SKU ಗಳ ಜೊತೆಗೆ ಟ್ರ್ಯಾಕ್ ಮಾಡಲು, ಮತ್ತು ತೊಡಕಿನ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್‌ಗಳಿಂದ ಪೂರೈಕೆದಾರರ ಆರ್ಡರ್‌ಗಳನ್ನು ನಿರ್ವಹಿಸಲು ಪ್ರಯತ್ನಿಸುತ್ತಿದ್ದಾಗ ನಾನು ಮುರಿಯುವ ಹಂತಕ್ಕೆ ತಲುಪಿದ್ದೆ. ನನಗೆ ಸಹಾಯ ಮಾಡುವ ಆಪ್ ಹುಡುಕಿದಾಗ, ನಾನು ಆರು ವಿಭಿನ್ನ ಆಯ್ಕೆಗಳನ್ನು ಪ್ರಯತ್ನಿಸಿದೆ. ಪ್ರತಿಯೊಂದೂ ಸಂಪೂರ್ಣವಾಗಿ ಅಪೂರ್ಣವಾಗಿತ್ತು, ನಂಬಲಾಗದಷ್ಟು ಗೊಂದಲಮಯವಾಗಿತ್ತು, ಅಥವಾ ಶೋಷಣೆ ಮಾಡುವಂತಿತ್ತು — ಮೂಲಭೂತ ಸಾಧನಗಳಿಗಾಗಿ ತಿಂಗಳಿಗೆ ನೂರಾರು ಡಾಲರ್‌ಗಳನ್ನು ವಿಧಿಸುತ್ತಿದ್ದವು.",
  "about.founder.p3": "ಸ್ವತಂತ್ರ ಸೃಷ್ಟಿಕರ್ತರನ್ನು ಶೋಷಿಸುವ ಉದ್ಯಮದಿಂದ ಬೇಸತ್ತು, ನನ್ನ ಸ್ವಂತ ಪರಿಹಾರವನ್ನು ನಿರ್ಮಿಸಲು ನಾನು ನಿರ್ಧರಿಸಿದೆ. ನನ್ನ ಸ್ವಂತ ವ್ಯವಹಾರಗಳನ್ನು ಸ್ವಚ್ಛವಾಗಿ, ಸಮರ್ಥವಾಗಿ ಮತ್ತು ಸಂಪೂರ್ಣ ಮನಶ್ಶಾಂತಿಯಿಂದ ನಡೆಸಲು ಅಗತ್ಯದಿಂದ Luminous StockHaven ಅನ್ನು ನಿರ್ಮಿಸಿದೆ.",
  "about.founder.p4": "ಪ್ರತಿ ಸಣ್ಣ ವ್ಯಾಪಾರಿಯೂ ತಮ್ಮ ಆದಾಯವನ್ನು ಅಪಾಯಕ್ಕೆ ಒಡ್ಡದೆ ನಿಜವಾಗಿಯೂ ಕೆಲಸ ಮಾಡುವ ಸಾಧನಗಳಿಗೆ ಅರ್ಹರಾಗಿರುವುದರಿಂದ, ಈ ವೇದಿಕೆಯನ್ನು ಪ್ರಾಮಾಣಿಕ, ಕೈಗೆಟುಕುವ ಬೆಲೆಗೆ ಸಾರ್ವಜನಿಕರಿಗೆ ತೆರೆಯಲು ನಾನು ನಿರ್ಧರಿಸಿದೆ. ನಾವು ಸ್ವತಂತ್ರವಾಗಿ ಮಾಲೀಕತ್ವ ಹೊಂದಿದ್ದೇವೆ, ನಮ್ಮ ಸಮುದಾಯವನ್ನು ತೀವ್ರವಾಗಿ ರಕ್ಷಿಸುತ್ತೇವೆ, ಮತ್ತು ಒಬ್ಬ ಚಿಲ್ಲರೆ ವ್ಯಾಪಾರಿಯಿಂದ, ಚಿಲ್ಲರೆ ವ್ಯಾಪಾರಿಗಳಿಗಾಗಿ ನಿರ್ಮಿಸಲ್ಪಟ್ಟಿದ್ದೇವೆ.",
  "notice.ariaLabel": "ಟ್ರೇಡ್‌ಮಾರ್ಕ್ ಮತ್ತು ಹಕ್ಕುಸ್ವಾಮ್ಯ ಸೂಚನೆ",
  "notice.heading": "🛡️ ಚಿಲ್ಲರೆ ವ್ಯಾಪಾರಿಗಳಿಗಾಗಿ ನಿರ್ಮಿಸಲಾಗಿದೆ, ಕಾರ್ಪೊರೇಟ್ ರಣಹದ್ದುಗಳಿಗೆ ಅಮೂಲ್ಯ",
  "notice.intro": "ನಾನು 5 ಅಂಗಡಿಗಳನ್ನು ನಡೆಸುತ್ತೇನೆ ಮತ್ತು ನೂರಾರು ಡಾಲರ್‌ಗಳ ಗೊಂದಲಮಯ ಸಾಫ್ಟ್‌ವೇರ್‌ನಿಂದ ಮೋಸಹೋಗುವುದರಿಂದ ಬೇಸತ್ತಿದ್ದರಿಂದ ನಾನು ಈ ಆಪ್ ಅನ್ನು ನಿರ್ಮಿಸಿದೆ. ಸ್ವತಂತ್ರ ಕಲಾವಿದರು, ಕುಶಲಕರ್ಮಿಗಳು, ಪುಸ್ತಕ ಮಾರಾಟಗಾರರು ಮತ್ತು ಸ್ಥಳೀಯ ಅಂಗಡಿಗಳನ್ನು ರಕ್ಷಿಸಲು ಈ ಆಪ್ ನಿರ್ಮಿಸಲಾಗಿದೆ.",
  "notice.legalHeading": "ಸ್ಪರ್ಧಿಗಳು ಮತ್ತು ಅನುಕರಿಸುವವರಿಗೆ ಕಾನೂನು ಸೂಚನೆ:",
  "notice.legalBody": "ನಾವು ಮಾರುಕಟ್ಟೆಯನ್ನು ಸಕ್ರಿಯವಾಗಿ ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡುತ್ತೇವೆ. ನಮ್ಮ ವೇದಿಕೆಯನ್ನು ಸ್ಕ್ರ್ಯಾಪ್ ಮಾಡಲು, ನಮ್ಮ ಸ್ವಾಮ್ಯದ ಕೆಲಸದ ಹರಿವುಗಳನ್ನು ಕ್ಲೋನ್ ಮಾಡಲು, ಅಥವಾ ನಮ್ಮ ಬೌದ್ಧಿಕ ಆಸ್ತಿಯನ್ನು ಉಲ್ಲಂಘಿಸಲು ಮಾಡುವ ಯಾವುದೇ ಪ್ರಯತ್ನವು ತಕ್ಷಣದ, ಆಕ್ರಮಣಕಾರಿ ಕಾನೂನು ಕ್ರಮವನ್ನು ಎದುರಿಸುತ್ತದೆ.",
  "notice.acquisitionHeading": "ಸ್ವಾಧೀನ ಸಂಸ್ಥೆಗಳು ಮತ್ತು ದಳ್ಳಾಳಿಗಳಿಗೆ:",
  "notice.acquisitionBody": "ನನಗೆ ಇಮೇಲ್ ಮಾಡಬೇಡಿ. ನನಗೆ ಸಂದೇಶ ಕಳುಹಿಸಬೇಡಿ. ನನಗೆ 'ತಂತ್ರಗತ ನಿರ್ಗಮನ'ವನ್ನು ಪ್ರಸ್ತಾಪಿಸಬೇಡಿ. ನೀವು ಸಾವಿರಾರು, ಲಕ್ಷಾಂತರ, ಕೋಟ್ಯಂತರ ಅಥವಾ ಟ್ರಿಲಿಯನ್‌ಗಳನ್ನು ನೀಡಬಹುದು — ಉತ್ತರ ಇಲ್ಲ. ನನ್ನ ಸಹ ವ್ಯಾಪಾರಿಗಳಿಗೆ ಬೆಲೆಗಳನ್ನು ಹೆಚ್ಚಿಸಲು ಮಾತ್ರ ನೀವು ಈ ಆಪ್ ಅನ್ನು ಖರೀದಿಸುವುದಿಲ್ಲ. ಕೇಳದ ಪ್ರತಿ ಸ್ವಾಧೀನ ಇಮೇಲ್ ಅನ್ನು ತಕ್ಷಣ ಸ್ಪ್ಯಾಮ್ ಎಂದು ಗುರುತಿಸಲಾಗುತ್ತದೆ, ಮತ್ತು ನಿಮ್ಮ ಡೊಮೇನ್ ಅನ್ನು ನಮ್ಮ ವೇದಿಕೆಯಿಂದ ಶಾಶ್ವತವಾಗಿ ನಿರ್ಬಂಧಿಸಲಾಗುತ್ತದೆ. ನಿಮ್ಮ ಶ್ರಮವನ್ನು ಉಳಿಸಿ.",
  "footer.trademarkLine": "ಅನಧಿಕೃತ ನಕಲು, ಕ್ಲೋನಿಂಗ್ ಅಥವಾ ಡೇಟಾ ಸ್ಕ್ರ್ಯಾಪಿಂಗ್ ಅನ್ನು ಕಟ್ಟುನಿಟ್ಟಾಗಿ ನಿಷೇಧಿಸಲಾಗಿದೆ.",
  "legalNav.viewPlans": "ಯೋಜನೆಗಳನ್ನು ನೋಡಿ",
