  "auth.notRegistered.body": "ಈ ಅಪ್ಲಿಕೇಶನ್ ಬಳಸಲು ನೀವು ನೋಂದಾಯಿಸಿಕೊಂಡಿಲ್ಲ. ಪ್ರವೇಶವನ್ನು ಕೋರಲು ದಯವಿಟ್ಟು ಅಪ್ಲಿಕೇಶನ್ ನಿರ್ವಾಹಕರನ್ನು ಸಂಪರ್ಕಿಸಿ.",
