  "subscribe.pastDue": "ನಿಮ್ಮ ಪಾವತಿ ಬಾಕಿಯಾಗಿದೆ. ಯೋಜನೆ ಆಯ್ಕೆಗಳ ಪುಟದಿಂದ ನಿಮ್ಮ ಪಾವತಿ ವಿಧಾನವನ್ನು ನೀವು ನವೀಕರಿಸಬಹುದು.",
  "subscribe.alreadyHasAccess": "ಈ ಖಾತೆಗೆ ಈಗಾಗಲೇ ಚಂದಾದಾರಿಕೆ ಪ್ರವೇಶವಿದೆ. ಯೋಜನೆಯ ಬದಲಾವಣೆಗಳು ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ ಚಂದಾದಾರಿಕೆ ಹರಿವನ್ನು ಬಳಸಬೇಕು.",
  "subscribe.reviewPlanOptions": "ಯೋಜನೆ ಆಯ್ಕೆಗಳನ್ನು ಪರಿಶೀಲಿಸಿ",
  "subscribe.openWorkspace": "ನಿಮ್ಮ ಕಾರ್ಯಕ್ಷೇತ್ರವನ್ನು ತೆರೆಯಿರಿ",
  "subscribe.chooseBusiness": "ಈ ಚಂದಾದಾರಿಕೆ ಸೇರುವ ವ್ಯವಹಾರವನ್ನು ಆರಿಸಿ. ಇದು ಚಂದಾದಾರಿಕೆಯನ್ನು ನಿಮ್ಮ ಕಾರ್ಯಕ್ಷೇತ್ರಕ್ಕೆ ಮಾತ್ರ ಸಂಪರ್ಕಿಸುತ್ತದೆ — ಇದು ಅಪ್ಲಿಕೇಶನ್ ಅನ್ನು ತೆರೆಯುವುದಿಲ್ಲ, ಪರೀಕ್ಷೆಯನ್ನು ಪ್ರಾರಂಭಿಸುವುದಿಲ್ಲ, ಅಥವಾ ಯಾವುದಕ್ಕೂ ಶುಲ್ಕ ವಿಧಿಸುವುದಿಲ್ಲ.",
  "subscribe.openWorkspaceFailed": "ಆ ಕಾರ್ಯಕ್ಷೇತ್ರವನ್ನು ತೆರೆಯಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
  "subscribe.setupWorkspaceFailed": "ನಿಮ್ಮ ಕಾರ್ಯಕ್ಷೇತ್ರವನ್ನು ಹೊಂದಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
  "subscribe.useWorkspace": "{name} ಬಳಸಿ",
  "subscribe.thisWorkspace": "ಈ ಕಾರ್ಯಕ್ಷೇತ್ರ",
  "subscribe.opening": "ತೆರೆಯಲಾಗುತ್ತಿದೆ…",
