  "subscribe.setupWorkspace": "ನನ್ನ ಕಾರ್ಯಕ್ಷೇತ್ರವನ್ನು ಹೊಂದಿಸಿ",
  "subscribe.settingUp": "ಹೊಂದಿಸಲಾಗುತ್ತಿದೆ…",
  "subscribe.noWorkspace": "ಈ ಖಾತೆಯಲ್ಲಿ ಇನ್ನೂ ಯಾವುದೇ ಕಾರ್ಯಕ್ಷೇತ್ರ ಲಭ್ಯವಿಲ್ಲ. ಸಹಾಯಕ್ಕಾಗಿ Luminous StockHaven ಬೆಂಬಲವನ್ನು ಸಂಪರ್ಕಿಸಿ.",
  "subscribe.noPaymentNote": "ಇಲ್ಲಿ ಯಾವುದೇ ಪಾವತಿಯನ್ನು ತೆಗೆದುಕೊಳ್ಳಲಾಗುತ್ತಿಲ್ಲ, ಮತ್ತು ಯಾವುದೇ ಪರೀಕ್ಷೆ ಪ್ರಾರಂಭವಾಗಿಲ್ಲ — ಕಾರ್ಯಕ್ಷೇತ್ರವನ್ನು ಆರಿಸುವುದು ಚಂದಾದಾರಿಕೆಯನ್ನು ಅದಕ್ಕೆ ಮಾತ್ರ ಸಂಪರ್ಕಿಸುತ್ತದೆ.",
  "subscribe.workspaceReady": "ನಿಮ್ಮ ಕಾರ್ಯಕ್ಷೇತ್ರ ಸಿದ್ಧವಾಗಿದೆ.",
  "subscribe.checkingTrial": "ನಿಮ್ಮ ಇಮೇಲ್‌ಗಾಗಿ ಉಚಿತ ಪರೀಕ್ಷೆ ಲಭ್ಯವಿದೆಯೇ ಎಂದು ಪರಿಶೀಲಿಸಲಾಗುತ್ತಿದೆ…",
  "subscribe.trialEligible": "ಅರ್ಹ ಹೊಸ ಗ್ರಾಹಕರಿಗೆ ಒಂದು 7 ದಿನಗಳ ಉಚಿತ ಪರೀಕ್ಷೆ ಸಿಗುತ್ತದೆ. ಇಂದು ನಿಮಗೆ ಶುಲ್ಕ ವಿಧಿಸಲಾಗುವುದಿಲ್ಲ — ನೀವು ಮೊದಲು ರದ್ದುಗೊಳಿಸದ ಹೊರತು ಪರೀಕ್ಷೆ ಮುಗಿದಾಗ ನಿಮ್ಮ ಮೊದಲ ಪಾವತಿ {price} ಬಾಕಿಯಾಗುತ್ತದೆ.",
