  "upgrade.downgradeWarning5": "ದಾಸ್ತಾನು ಸ್ವತಃ ಸರಾಗವಾಗಿ Essentials ಗೆ ಸಾಗುತ್ತದೆ — ನೀವು ಸಂಗ್ರಹಿಸಿದ ಯಾವುದನ್ನೂ ಅಳಿಸಲಾಗುವುದಿಲ್ಲ.",
