  "upgrade.doneTrial": "ನಿಮ್ಮ ಪರೀಕ್ಷೆ {trialEnds} ವರೆಗೆ ಮುಂದುವರಿಯುತ್ತದೆ, ನಂತರ Business ತಿಂಗಳಿಗೆ $29.99 ರಲ್ಲಿ ಪ್ರಾರಂಭವಾಗುತ್ತದೆ. ನಿಮ್ಮ ಮೊದಲ Business ಶುಲ್ಕವು {firstCharge} ರಂದು ಇದೆ.",
  "upgrade.doneUpgradeNow": "Business ಈಗ ತಿಂಗಳಿಗೆ $29.99 ರಲ್ಲಿ ಪ್ರಾರಂಭವಾಗುತ್ತದೆ. ಬೆಲೆ ವ್ಯತ್ಯಾಸವು ನಿಮ್ಮ ಮುಂದಿನ ಇನ್‌ವಾಯ್ಸ್‌ನಲ್ಲಿ ಬರುತ್ತದೆ — ತಕ್ಷಣದ ಶುಲ್ಕವಿಲ್ಲ.",
