  "upgrade.previewDowngradeNote": "ಡೌನ್‌ಗ್ರೇಡ್ ನಿಮ್ಮ ಪಾವತಿಸಿದ ಅವಧಿಯ ಅಂತ್ಯದಲ್ಲಿ ಜಾರಿಗೆ ಬರುತ್ತದೆ. ನಿಮ್ಮ ಕಳೆದುಹೋದ-ವೈಶಿಷ್ಟ್ಯದ ಡೇಟಾವನ್ನು ಇರಿಸಲಾಗುತ್ತದೆ ಆದರೆ ಪ್ರವೇಶಿಸಲಾಗುವುದಿಲ್ಲ — ಡೌನ್‌ಗ್ರೇಡ್‌ನ ಅಡ್ಡ ಪರಿಣಾಮವಾಗಿ ಅದನ್ನು ಎಂದಿಗೂ ಅಳಿಸಲಾಗುವುದಿಲ್ಲ.",
