  'products.bulkQuantityHint': 'ಆಯ್ಕೆಯ ಪ್ರತಿಯೊಂದು ಉತ್ಪನ್ನವು ಈ ಸಂಖ್ಯೆಯಲ್ಲಿ ಕೊನೆಗೊಳ್ಳುತ್ತದೆ, ಆಯ್ಕೆಮಾಡಿದ ಸ್ಥಳದಲ್ಲಿ. ಪ್ರತಿಯೊಂದು ಬದಲಾವಣೆಯು ಸ್ಟಾಕ್ ಚಲನೆಯಾಗಿ ದಾಖಲಾಗುತ್ತದೆ — ಎಂದಿಗೂ ಮೌನವಾಗಿ ಬದಲಾಯಿಸಲಾಗುವುದಿಲ್ಲ. ಆರ್ಕೈವ್ ಮಾಡಿದ ಉತ್ಪನ್ನಗಳನ್ನು ಬಿಟ್ಟುಬಿಡಲಾಗುತ್ತದೆ.',
