  "products.bulkDeleteWarning": "ಅಳಿಸುವುದು ಶಾಶ್ವತ. ಈ ಉತ್ಪನ್ನಗಳು ಮತ್ತು ಅವುಗಳ ಸ್ಟಾಕ್ ಪ್ರಮಾಣಗಳು ಶಾಶ್ವತವಾಗಿ ಹೋಗುತ್ತವೆ; ಉತ್ಪನ್ನ ಸಂಖ್ಯೆ ಕಡಿಮೆಯಾಗಲು ಏಕೈಕ ಮಾರ್ಗ ಅಳಿಸುವುದು. ಆಯ್ಕೆಯಲ್ಲಿರುವ ಆರ್ಕೈವ್ ಮಾಡಿದ ಉತ್ಪನ್ನಗಳೂ ಅಳಿಸಲ್ಪಡುತ್ತವೆ. ಹಳೆಯ ಸ್ಟಾಕ್ ಚಲನೆಗಳು ಮತ್ತು ಆರ್ಡರ್‌ಗಳು ಆ ಸಮಯದಲ್ಲಿ ದಾಖಲಾದ ಉತ್ಪನ್ನದ ಹೆಸರನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತವೆ, ಆದ್ದರಿಂದ ನಿಮ್ಮ ದಾಖಲೆಗಳು ಓದಲು ಸುಲಭವಾಗಿರುತ್ತವೆ.",
