  "exports.eyebrow": "ಡೇಟಾ",
  "exports.title": "ರಫ್ತುಗಳು ಮತ್ತು ಬ್ಯಾಕಪ್‌ಗಳು",
  "exports.subtitleStart": "ಡೌನ್‌ಲೋಡ್‌ಗಳು ಯಾವಾಗಲೂ ಇವುಗಳಿಗೆ ಸೀಮಿತವಾಗಿವೆ",
  "exports.subtitleRest": ". ಪ್ರತಿ ಫೈಲ್ ಅನ್ನು ವ್ಯವಹಾರದ ಹೆಸರು ಮತ್ತು ಅದನ್ನು ತಯಾರಿಸಿದ ದಿನಾಂಕದೊಂದಿಗೆ ಲೇಬಲ್ ಮಾಡಲಾಗಿದೆ.",
  "exports.createBusinessFirst": "ಮೊದಲು ವ್ಯವಹಾರವನ್ನು ರಚಿಸಿ — ರಫ್ತುಗಳು ವ್ಯವಹಾರಕ್ಕೆ ಸೇರುತ್ತವೆ, ಅಪ್ಲಿಕೇಶನ್‌ಗೆ ಅಲ್ಲ.",
  "exports.lockedTitle": "CSV ಮತ್ತು Excel ರಫ್ತುಗಳು Business ವೈಶಿಷ್ಟ್ಯವಾಗಿದೆ",
  "exports.lockedDesc": "ನಿಮ್ಮ ಕಾರ್ಯಕ್ಷೇತ್ರವು Essentials ಯೋಜನೆಯಲ್ಲಿದೆ. Business CSV ಮತ್ತು Excel ರಫ್ತುಗಳು, ದಾಸ್ತಾನು ಮೌಲ್ಯಮಾಪನ, ಅನಿಯಮಿತ ಉತ್ಪನ್ನಗಳು ಮತ್ತು ಸಿಬ್ಬಂದಿ, ಪೂರೈಕೆದಾರರು, ಖರೀದಿ ಮತ್ತು ಬಂಡಲ್‌ಗಳನ್ನು ಸೇರಿಸುತ್ತದೆ.",
  "exports.seeBusiness": "Business ಏನು ಒಳಗೊಂಡಿದೆ ಎಂದು ನೋಡಿ",
  "exports.whatTheseAre": "ಈ ಫೈಲ್‌ಗಳು ಯಾವುವು",
  "exports.about1": "ಪ್ರತಿ ಡೇಟಾಸೆಟ್ CSV ಅಥವಾ ನಿಜವಾದ Excel ಕಾರ್ಯಪುಸ್ತಕ (.xlsx) ಆಗಿ ಬರುತ್ತದೆ — ಪೂರ್ಣ ದಾಸ್ತಾನು ಕಾರ್ಯಪುಸ್ತಕವು Excel-ಮಾತ್ರ, ಪ್ರತಿ ಡೇಟಾಸೆಟ್‌ಗೆ ಒಂದು ಶೀಟ್‌ನೊಂದಿಗೆ. CSV ಫೈಲ್‌ಗಳು Excel, Numbers, Google Sheets ಮತ್ತು ಹೆಚ್ಚಿನ ದಾಸ್ತಾನು ಅಪ್ಲಿಕೇಶನ್‌ಗಳಲ್ಲಿ ತೆರೆಯುತ್ತವೆ. UTF-8 ಪಠ್ಯ, ಉಲ್ಲೇಖಿಸಿದ ಅಲ್ಪವಿರಾಮಗಳು, ಟಿಪ್ಪಣಿಗಳಲ್ಲಿನ ಸಾಲು ವಿರಾಮಗಳು ಮತ್ತು ಕೋಡ್‌ಗಳಲ್ಲಿನ ಮುಂಚೂಣಿಯ ಸೊನ್ನೆಗಳೆಲ್ಲವೂ ಸಂರಕ್ಷಿಸಲ್ಪಡುತ್ತವೆ, ಮತ್ತು ಸೂತ್ರದಂತೆ ಪ್ರಾರಂಭವಾಗುವ ಕೋಶಗಳನ್ನು ತಟಸ್ಥಗೊಳಿಸಲಾಗುತ್ತದೆ ಇದರಿಂದ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್ ಅವುಗಳನ್ನು ಪಠ್ಯವಾಗಿ ತೆರೆಯುತ್ತದೆ.",
  "exports.about2": "Excel ಫೈಲ್‌ಗಳಲ್ಲಿ, SKU ಗಳು, UPC ಗಳು, ISBN ಗಳು ಮತ್ತು ಬಾರ್‌ಕೋಡ್‌ಗಳು ಪಠ್ಯ ಕೋಶಗಳಾಗಿವೆ — ಎಂದಿಗೂ ವೈಜ್ಞಾನಿಕ ಸಂಕೇತವಲ್ಲ ಮತ್ತು ಎಂದಿಗೂ ಕತ್ತರಿಸಿದ ಸೊನ್ನೆಗಳಲ್ಲ — ಕಾಲಮ್ ಅಗಲಗಳು, ಹೆಡರ್ ಫಿಲ್ಟರ್‌ಗಳು ಮತ್ತು ಕರೆನ್ಸಿ ಅಥವಾ ಪ್ರಮಾಣ ಸ್ವರೂಪಗಳನ್ನು ಅನ್ವಯಿಸಲಾಗಿದೆ. ಪೂರ್ಣ ದಾಸ್ತಾನು ಕಾರ್ಯಪುಸ್ತಕವು ಉತ್ಪನ್ನಗಳು, ದಾಸ್ತಾನು ಮಟ್ಟಗಳು, ಸ್ಥಳಗಳು ಮತ್ತು ಚಲನೆಗಳನ್ನು ಪ್ರತ್ಯೇಕ ಶೀಟ್‌ಗಳಲ್ಲಿ ಇರಿಸುತ್ತದೆ.",
  "exports.about3": "ಬಹಳ ದೊಡ್ಡ ರಫ್ತುಗಳು ಪ್ರತಿ ಡೇಟಾಸೆಟ್‌ಗೆ 20,000 ಸಾಲುಗಳಲ್ಲಿ ನಿಲ್ಲುತ್ತವೆ — ಅದು ಸಂಭವಿಸಿದಾಗ ಫೈಲ್ ಹೆಸರು ಹಾಗೆ ಹೇಳುತ್ತದೆ (truncated-20000), ಆದ್ದರಿಂದ ಭಾಗಶಃ ಫೈಲ್ ಎಂದಿಗೂ ಸಂಪೂರ್ಣವಾಗಿ ಹಾದುಹೋಗುವುದಿಲ್ಲ.",
  "exports.about4": "ಬ್ಯಾಕಪ್ ನಿಮ್ಮ ಡೇಟಾದ ಸ್ನ್ಯಾಪ್‌ಶಾಟ್ ಆಗಿದೆ, ಒಂದು-ಕ್ಲಿಕ್ ಮರುಸ್ಥಾಪನೆ ಅಲ್ಲ. ಅದನ್ನು ಮರುಸ್ಥಾಪಿಸುವುದು ಹಸ್ತಚಾಲಿತ, ಪರಿಶೀಲನೆ-ಮೊದಲ ಕೆಲಸವಾಗಿದೆ, ಆದ್ದರಿಂದ ಫೈಲ್ ಅನ್ನು ಸುರಕ್ಷಿತವಾಗಿರಿಸಿ — ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿ ಏನೂ ಅದರಿಂದ ಅಳಿಸಿದ ವ್ಯವಹಾರವನ್ನು ಇನ್ನೂ ಮರುರಚಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ. ಅಪ್ಲಿಕೇಶನ್ ಕೋಡ್ ಮತ್ತು Base44 ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಬ್ಯಾಕಪ್‌ಗಳನ್ನು ಈ ಫೈಲ್‌ಗಳಿಂದ ಪ್ರತ್ಯೇಕವಾಗಿ ನಿರ್ವಹಿಸಲಾಗುತ್ತದೆ.",
  "exports.about5": "ಫೋಟೋಗಳು ಮತ್ತು ಲಗತ್ತುಗಳನ್ನು ಅವುಗಳ ಸಂಗ್ರಹಿಸಿದ ಲಿಂಕ್‌ಗಳಾಗಿ ಪಟ್ಟಿ ಮಾಡಲಾಗಿದೆ — ಚಿತ್ರ ಫೈಲ್‌ಗಳನ್ನು ಸ್ವತಃ ಡೌನ್‌ಲೋಡ್‌ಗೆ ಪ್ಯಾಕ್ ಮಾಡಲಾಗಿಲ್ಲ.",
  "exports.backupTitle": "ಪೂರ್ಣ ಬ್ಯಾಕಪ್",
  "exports.backupDesc": "ಈ ವ್ಯವಹಾರದ ಉತ್ಪನ್ನಗಳು, ಸ್ಥಳಗಳು, ದಾಸ್ತಾನು ಮಟ್ಟಗಳು, ಸಂಪೂರ್ಣ ಚಲನೆ ಲೆಡ್ಜರ್, ಪೂರೈಕೆದಾರರು, ಖರೀದಿ, ಆದೇಶಗಳು, ಹಿಂತಿರುಗಿಸುವಿಕೆಗಳು, ಎಣಿಕೆಗಳು ಮತ್ತು ಪಟ್ಟಿಗಳೊಂದಿಗೆ ಒಂದು ಫೈಲ್ — ಜೊತೆಗೆ ಅದರ ಪ್ರೊಫೈಲ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳು. ನೀವು ನಿಯಂತ್ರಿಸುವ ಎಲ್ಲೋ ಅದನ್ನು ಇರಿಸಿ.",
  "exports.backupIncludes1": "ಉತ್ಪನ್ನಗಳು, ಕೋಡ್‌ಗಳು, ವೆಚ್ಚಗಳು ಮತ್ತು ಟಿಪ್ಪಣಿಗಳು",
  "exports.backupIncludes2": "ಸ್ಥಳಗಳು ಮತ್ತು ಪ್ರತಿ-ಸ್ಥಳ ಪ್ರಮಾಣಗಳು",
  "exports.backupIncludes3": "ಪ್ರತಿ ಚಲನೆ, ನಟ ಮತ್ತು ಸಮಯದೊಂದಿಗೆ",
  "exports.backupIncludes4": "ಖರೀದಿ, ಆದೇಶಗಳು, ಹಿಂತಿರುಗಿಸುವಿಕೆಗಳು ಮತ್ತು ಎಣಿಕೆಗಳು",
