  "print.footerReceipt": "ಪಾವತಿಯನ್ನು ಹಸ್ತಚಾಲಿತವಾಗಿ ದಾಖಲಿಸಲಾಗುತ್ತದೆ. ಈ ರಸೀದಿಯು ಸ್ವತಃ ಕಾರ್ಡ್‌ಗೆ ಶುಲ್ಕ ವಿಧಿಸುವುದಿಲ್ಲ.",
  "print.footerInvoice": "ಮೊತ್ತಗಳು ಆದೇಶದಲ್ಲಿ ನಮೂದಿಸಿದಂತೆಯೇ ಇವೆ. ಪಾವತಿಯನ್ನು ಹಸ್ತಚಾಲಿತವಾಗಿ ಟ್ರ್ಯಾಕ್ ಮಾಡಲಾಗುತ್ತದೆ, ಈ ದಾಖಲೆಯಿಂದ ಸಂಗ್ರಹಿಸಲಾಗುವುದಿಲ್ಲ.",
