  "settings.details.address": "ವಿಳಾಸ",
  'settings.details.taxRate': 'ನನ್ನ ತೆರಿಗೆ ದರ',
  'settings.details.taxRateHint': 'ಒಮ್ಮೆ ಹೊಂದಿಸಿ. ಪ್ರತಿ ಹೊಸ ಮಾರಾಟ ಆದೇಶವು ಈ ದರದಿಂದ ತನ್ನ ತೆರಿಗೆಯನ್ನು ತಾನೇ ತುಂಬುತ್ತದೆ — ಆದರೂ ನೀವು ಯಾವುದೇ ಒಂದು ಆದೇಶದಲ್ಲಿ ತೆರಿಗೆಯನ್ನು ಬದಲಾಯಿಸಬಹುದು.',
  "settings.details.taxMode": "ಆರ್ಡರ್‌ಗಳು ತಮ್ಮ ತೆರಿಗೆಯನ್ನು ಹೇಗೆ ಪಡೆಯುತ್ತವೆ",
  "settings.details.taxModeFixed": "ನನ್ನ ನಿಗದಿತ ದರ",
  "settings.details.taxModeAutomatic": "ಸ್ವಯಂಚಾಲಿತ — ಗ್ರಾಹಕರ ರಾಜ್ಯದ ಪ್ರಕಾರ",
  "settings.details.taxModeHint": "ನಿಗದಿತ ಮೋಡ್ ಪ್ರತಿ ಹೊಸ ಆರ್ಡರ್‌ನಲ್ಲಿ ನಿಮ್ಮ ದರವನ್ನು ಬಳಸುತ್ತದೆ. ಸ್ವಯಂಚಾಲಿತ ಮೋಡ್, ರಾಜ್ಯವು ಆರ್ಡರ್‌ನಲ್ಲಿ ಇದ್ದ ಕೂಡಲೇ, ಹೊಸ ಆರ್ಡರ್‌ನ ತೆರಿಗೆಯನ್ನು ಗ್ರಾಹಕರ ರಾಜ್ಯದ ಮೂಲ ದರದಿಂದ ತುಂಬುತ್ತದೆ, ಮತ್ತು ರಾಜ್ಯ ಬದಲಾದರೆ ಅದನ್ನು ಮತ್ತೆ ತುಂಬುತ್ತದೆ. ಇವು ರಾಜ್ಯದ ಮೂಲ ದರಗಳು — ಸ್ಥಳೀಯ ತೆರಿಗೆಗಳು ಇನ್ನಷ್ಟು ಸೇರಿಸಬಹುದು. ಯಾವುದೇ ರಾಜ್ಯವಿಲ್ಲದ, ಅಥವಾ US ನ ಹೊರಗಿನ ಆರ್ಡರ್, ಮೇಲೆ ನೀಡಿರುವ ನಿಮ್ಮ ನಿಗದಿತ ದರವನ್ನು ಬಳಸುತ್ತದೆ.",
  'settings.details.gs1Prefix': "GS1 ಕಂಪನಿ ಪೂರ್ವಪ್ರತ್ಯಯ",
  'settings.details.gs1PrefixHint': "GS1 ನಿಂದ ಪೂರ್ವಪ್ರತ್ಯಯದ ಪರವಾನಗಿ ಇದ್ದರೆ ಮಾತ್ರ. ಅದನ್ನು ಒಮ್ಮೆ ಹೊಂದಿಸಿ, ಉತ್ಪನ್ನ ಫಾರ್ಮ್‌ನ ಕೋಡ್ ಜನರೇಟರ್ ನಿಮ್ಮ ಸ್ವಂತ ಸಂಖ್ಯೆಗಳಿಂದ ನಿಜವಾದ ಚಿಲ್ಲರೆ UPC ಮತ್ತು EAN ಕೋಡ್‌ಗಳನ್ನು ತಯಾರಿಸಬಹುದು — ಪ್ರತಿಯೊಂದೂ ಒಮ್ಮೆ ಮಾತ್ರ ಬಳಕೆಯಾಗುತ್ತದೆ, ಮತ್ತೆ ಎಂದಿಗೂ ಇಲ್ಲ. ನಿಮ್ಮ ಬಳಿ ಇಲ್ಲದಿದ್ದರೆ ಖಾಲಿ ಬಿಡಿ; ಆಪ್ ಎಂದಿಗೂ ಪೂರ್ವಪ್ರತ್ಯಯವನ್ನು ಸೃಷ್ಟಿಸುವುದಿಲ್ಲ.",
  'settings.details.gs1LearnMore': "GS1 ಗೆ ಹೊಸಬರೇ? ನೀವು ನಿಮ್ಮ ಸ್ವಂತ ದೇಶದಲ್ಲಿ ವಾಸಿಸುತ್ತಿದ್ದರೆ, ಇನ್ನಷ್ಟು ತಿಳಿಯಲು ಆ ದೇಶದ ಲಿಂಕ್ ಬಳಸಿ; ನೀವು ಯುನೈಟೆಡ್ ಸ್ಟೇಟ್ಸ್‌ನಲ್ಲಿ ವಾಸಿಸುತ್ತಿದ್ದರೆ, GS1 US ಲಿಂಕ್ ಬಳಸಿ.",
