  "settings.logout": "ಲಾಗ್ ಔಟ್",
  "settings.pastDue.body": "ನಿಮ್ಮ ಕೊನೆಯ ಪಾವತಿ ಪೂರ್ಣಗೊಂಡಿಲ್ಲ. ವಿಫಲ ಪಾವತಿಯಿಂದ 14 ದಿನಗಳವರೆಗೆ ನೀವು ಅದನ್ನು ಸರಿಪಡಿಸುವವರೆಗೆ ಪೂರ್ಣ ಬಳಕೆಯನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತೀರಿ. ಅದನ್ನು ಸರಿಪಡಿಸದಿದ್ದರೆ, ಚಂದಾದಾರಿಕೆ ರದ್ದುಗೊಳ್ಳುತ್ತದೆ, ಕಾರ್ಯಕ್ಷೇತ್ರವು 15 ದಿನಗಳವರೆಗೆ ವೀಕ್ಷಣೆ-ಮಾತ್ರವಾಗುತ್ತದೆ, ಮತ್ತು ನಂತರ ಖಾತೆ ಮತ್ತು ಅದರ ಎಲ್ಲಾ ಮಾಹಿತಿಯನ್ನು ಅಳಿಸಲಾಗುತ್ತದೆ. ಅಳಿಸುವ ಮೊದಲು ಯಾವುದೇ ಸಮಯದಲ್ಲಿ ಪಾವತಿಸುವುದರಿಂದ ಎಲ್ಲವೂ ಮರಳಿ ಬರುತ್ತದೆ. ಏನು ಮಾಡಬೇಕೆಂದು ಖಚಿತವಿಲ್ಲದಿದ್ದರೆ, theluminousbookshop@outlook.com ನಲ್ಲಿ ಬೆಂಬಲವನ್ನು ಸಂಪರ್ಕಿಸಿ.",
