  "payroll.dd.steps.body": "1. ACH ಪಾವತಿಗಳನ್ನು ಕಳುಹಿಸಬಹುದಾದ ವ್ಯವಹಾರ ಬ್ಯಾಂಕ್ ಖಾತೆ ನಿಮಗೆ ಬೇಕು. 2. ಪ್ರತಿ ತಂಡದ ಸದಸ್ಯರಿಂದ ಸಹಿ ಮಾಡಿದ ಅಧಿಕಾರ ಫಾರ್ಮ್ ಅನ್ನು ಸಂಗ್ರಹಿಸಿ - ರದ್ದಾದ ಚೆಕ್ ಸಂಖ್ಯೆಗಳನ್ನು ಪರಿಶೀಲಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ. 3. ಹಣವು ಸಮಯಕ್ಕೆ ಸರಿಯಾಗಿ ತಲುಪುವಂತೆ ವೇತನ ದಿನಕ್ಕೆ 2-3 ವ್ಯವಹಾರ ದಿನಗಳ ಮೊದಲು ಪೇರೋಲ್ ಕಳುಹಿಸಿ. 4. ಹೆಚ್ಚಿನ ರಾಜ್ಯಗಳಿಗೆ ತಂಡದ ಸದಸ್ಯರ ಲಿಖಿತ ಒಪ್ಪಿಗೆ ಬೇಕು. ಈ ಅಪ್ಲಿಕೇಶನ್ ಫಾರ್ಮ್‌ಗಳನ್ನು ಸಂಗ್ರಹಿಸುತ್ತದೆ ಮತ್ತು ಹಂತಗಳ ಮೂಲಕ ನಿಮ್ಮನ್ನು ಕರೆದೊಯ್ಯುತ್ತದೆ - ಹಣವನ್ನು ನಿಜವಾಗಿ ಕಳುಹಿಸುವುದು ನಿಮ್ಮ ಸ್ವಂತ ಬ್ಯಾಂಕ್ ಮೂಲಕ ನಡೆಯುತ್ತದೆ.",
