  "training.warningSentOn": "ಎಚ್ಚರಿಕೆ ಕಳುಹಿಸಲಾಗಿದೆ {date}",
  "auth.sameEmailNotice": "Google Play ಅಥವಾ App Store ನಿಂದ ನಮ್ಮ ಅಪ್ಲಿಕೇಶನ್ ಈಗಾಗಲೇ ನಿಮ್ಮ ಬಳಿ ಇದೆಯೇ? ಇಲ್ಲಿ ಅದೇ ಇಮೇಲ್ ಬಳಸಿ — ನೀವು ಅಪ್ಲಿಕೇಶನ್‌ಗೆ ಸೈನ್ ಇನ್ ಮಾಡುವ ಇಮೇಲ್ — ಆದ್ದರಿಂದ ನಿಮ್ಮ ಅಂಗಡಿ ಮತ್ತು ನಿಮ್ಮ ದಾಸ್ತಾನು ನಿಮ್ಮೊಂದಿಗೆ ಬರುತ್ತದೆ. ಬೇರೆ ಇಮೇಲ್ ಸಂಪೂರ್ಣ ಹೊಸ, ಖಾಲಿ ಅಂಗಡಿಯನ್ನು ಪ್ರಾರಂಭಿಸುತ್ತದೆ.",
