  "recovery.title": "ನಿಮ್ಮ ಖಾತೆಯನ್ನು ಮರುಪಡೆಯಿರಿ",
  "recovery.subtitle": "ನಿಮ್ಮ ಖಾತೆಯು ಇರುವ ಇಮೇಲ್‌ಗೆ ಪ್ರವೇಶವನ್ನು ಕಳೆದುಕೊಂಡಿದ್ದೀರಾ? ನಿಮ್ಮ ಬಿಡಿ ಕೀಗಳು ನಿಮ್ಮನ್ನು ಮರಳಿ ನಿಮ್ಮ ಅಂಗಡಿಗೆ ಕರೆತರಬಹುದು.",
