  "rewards.give.detailPlaceholder": "ಬಹುಮಾನವನ್ನು ನಿಮ್ಮ ಸ್ವಂತ ಪದಗಳಲ್ಲಿ ವಿವರಿಸಿ",
  "rewards.give.help": "ಬಹುಮಾನಗಳು ಒಬ್ಬ ತಂಡದ ಸದಸ್ಯರಿಗೆ ಹೋಗುತ್ತವೆ. ವ್ಯವಸ್ಥಾಪಕರು ಸಿಬ್ಬಂದಿಗೆ ಬಹುಮಾನ ನೀಡುತ್ತಾರೆ; ಮಾಲೀಕರು ತಂಡದ ಯಾರಿಗಾದರೂ ಬಹುಮಾನ ನೀಡಬಹುದು.",
