  "rewards.redeem.help": "ತಂಡದ ಸದಸ್ಯರು ನಿಮಗೆ ತೋರಿಸುವ ಕೋಡ್ ಅನ್ನು ಟೈಪ್ ಮಾಡಿ. ಪ್ರತಿ ಕೋಡ್ ಒಮ್ಮೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ.",
