  "pos.clover.connectedToast": "Clover ಸಂಪರ್ಕಿಸಲಾಗಿದೆ. ಅದರ ಮಾರಾಟಗಳು ಈಗ ಇಲ್ಲಿ ಎಣಿಕೆಯಾಗುತ್ತವೆ.",
