  "pos.toast.help": "Toast, Toast ನ ಪಾಲುದಾರ ಕಾರ್ಯಕ್ರಮದ ಮೂಲಕ ಸಂಪರ್ಕಗೊಳ್ಳುತ್ತದೆ. ನಿಮ್ಮ ರೆಸ್ಟೋರೆಂಟ್‌ನ ಪಾಲುದಾರ ರುಜುವಾತುಗಳು ಸಿದ್ಧವಾದಾಗ, ಅವುಗಳನ್ನು ಇಲ್ಲಿ ಅಂಟಿಸಿ ಮತ್ತು ಪ್ರತಿ Toast ಮಾರಾಟವು ತಾನೇ ಇಲ್ಲಿ ದಾಸ್ತಾನಿನಿಂದ ತನ್ನ ವಸ್ತುಗಳನ್ನು ತೆಗೆದುಹಾಕುತ್ತದೆ.",
