  "pos.toast.restaurantPlaceholder": "ರೆಸ್ಟೋರೆಂಟ್ GUID",
  "pos.toast.credentialNote": "Toast ಈ ರುಜುವಾತುಗಳನ್ನು ಅದರ ಪಾಲುದಾರ ಕಾರ್ಯಕ್ರಮದ ಮೂಲಕ ನೀಡುತ್ತದೆ. ಅವುಗಳನ್ನು ಸರ್ವರ್‌ನಲ್ಲಿ ಮಾತ್ರ ಸಂಗ್ರಹಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಎಂದಿಗೂ ಮರಳಿ ತೋರಿಸಲಾಗುವುದಿಲ್ಲ.",
  "pos.lightspeed.help": "ನಿಮ್ಮ Lightspeed Retail (X-Series) ಅಂಗಡಿಯನ್ನು ಸಂಪರ್ಕಿಸಿ ಮತ್ತು ಪ್ರತಿ ಪೂರ್ಣಗೊಂಡ ಮಾರಾಟವು ತಾನೇ ಇಲ್ಲಿ ದಾಸ್ತಾನಿನಿಂದ ತನ್ನ ವಸ್ತುಗಳನ್ನು ತೆಗೆದುಹಾಕುತ್ತದೆ.",
