  "pos.lightspeed.connectedToast": "Lightspeed ಸಂಪರ್ಕಿಸಲಾಗಿದೆ. ಅದರ ಮಾರಾಟಗಳು ಈಗ ಇಲ್ಲಿ ಎಣಿಕೆಯಾಗುತ್ತವೆ.",
  "pos.lightspeed.domainPlaceholder": "ಡೊಮೇನ್ ಪೂರ್ವಪ್ರತ್ಯಯ — .retail.lightspeed.app ಗಿಂತ ಮೊದಲಿನ ಭಾಗ",
  "pos.lightspeed.tokenPlaceholder": "ನಿಮ್ಮ Lightspeed ಅಂಗಡಿಯಿಂದ API ಟೋಕನ್",
  "pos.lightspeed.tokenNote": "ಟೋಕನ್ ನಿಮ್ಮ Lightspeed ಅಂಗಡಿಯ API ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಂದ ಬರುತ್ತದೆ. ಅದನ್ನು ಸರ್ವರ್‌ನಲ್ಲಿ ಮಾತ್ರ ಸಂಗ್ರಹಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಎಂದಿಗೂ ಮರಳಿ ತೋರಿಸಲಾಗುವುದಿಲ್ಲ.",
