  "profile.title": "ನಿಮ್ಮ ಪ್ರೊಫೈಲ್ ಫೋಟೋ",
  "profile.ownerDesc": "ನಿಮ್ಮ ಫೋಟೋ ಮತ್ತು ನಿಮ್ಮ ತಂಡವು ನಿಮ್ಮನ್ನು ಗುರುತಿಸುವ ಹೆಸರು. ನಿಮ್ಮ ಸ್ವಂತ ಫೋಟೋ ತಕ್ಷಣವೇ ಕಾಣುತ್ತದೆ — ಅನುಮೋದನೆ ಅಗತ್ಯವಿಲ್ಲ.",
  "profile.memberDesc": "ಮಾಲೀಕರು ಅನುಮೋದಿಸಿದ ನಂತರ ನಿಮ್ಮ ಫೋಟೋ ನಿಮ್ಮ ಹೆಸರಿನ ಪಕ್ಕದಲ್ಲಿ ಕಾಣುತ್ತದೆ. ಅಲ್ಲಿಯವರೆಗೆ, ನಿಮ್ಮ ಹೆಸರಿನ ಮೊದಲಕ್ಷರಗಳು ಮಾತ್ರ ಕಾಣುತ್ತವೆ.",
  "profile.stateApproved": "ಇದೇ ಫೋಟೋವನ್ನು ನಿಮ್ಮ ತಂಡ ನೋಡುತ್ತದೆ.",
  "profile.stateNone": "ನೀವು ಇನ್ನೂ ಫೋಟೋವನ್ನು ಸೇರಿಸಿಲ್ಲ.",
  "profile.statePending": "ನಿಮ್ಮ ಫೋಟೋ ಮಾಲೀಕರ ಅನುಮೋದನೆಗಾಗಿ ಕಾಯುತ್ತಿದೆ. ಅವರು ಅನುಮೋದಿಸುವವರೆಗೆ ಅದು ಎಲ್ಲಿಯೂ ಕಾಣುವುದಿಲ್ಲ.",
  "profile.stateChangePending": "ನಿಮ್ಮ ಹೊಸ ಫೋಟೋ ಮಾಲೀಕರ ಅನುಮೋದನೆಗಾಗಿ ಕಾಯುತ್ತಿದೆ. ಅಲ್ಲಿಯವರೆಗೆ ನಿಮ್ಮ ಪ್ರಸ್ತುತ ಫೋಟೋ ಹಾಗೆಯೇ ಉಳಿಯುತ್ತದೆ.",
