  "profile.declinedChange": "ನಿಮ್ಮ ಫೋಟೋವನ್ನು ಅನುಮೋದಿಸಲಾಗಿಲ್ಲ — ಆದರೆ ನಿಮ್ಮ ಇನ್ನೊಂದು ಫೋಟೋ ಇನ್ನೂ ಇದೆ. ಅದನ್ನು ಬದಲಾಯಿಸಲು ಬಯಸಿದರೆ, ಬೇರೆ ಫೋಟೋವನ್ನು ಪ್ರಯತ್ನಿಸಿ.",
