  "profile.approvalsDesc": "ನೀವು ಅನುಮೋದಿಸುವವರೆಗೆ ತಂಡದ ಫೋಟೋ ಎಲ್ಲಿಯೂ ಕಾಣುವುದಿಲ್ಲ. ನೀವು ಅನುಮೋದಿಸದಿದ್ದರೆ, ಆ ವ್ಯಕ್ತಿಗೆ ಬೇರೆ ಫೋಟೋವನ್ನು ಆಯ್ಕೆಮಾಡಲು ಕೇಳಲಾಗುತ್ತದೆ.",
