  "restaurant.subtitle": "ಖಾದ್ಯವನ್ನು ನೀವು ಮಾರುವುದಕ್ಕೆ ಲಿಂಕ್ ಮಾಡಿ, ಮತ್ತು ಅದರ ಪದಾರ್ಥಗಳು ತಮ್ಮನ್ನು ತಾವೇ ನೋಡಿಕೊಳ್ಳುತ್ತವೆ — ಪ್ರತಿ ಮಾರಾಟವು ಅವುಗಳನ್ನು ಶೆಲ್ಫ್‌ನಿಂದ ತೆಗೆದುಹಾಕುತ್ತದೆ, ಮತ್ತು ಖಾದ್ಯ ಪುಟವು ಅದರ ನಿಜವಾದ ವೆಚ್ಚ ಏನು ಎಂಬುದನ್ನು ತೋರಿಸುತ್ತದೆ.",
