  "recipes.dialogIntro": "ಪಾಕವಿಧಾನವು ಖಾದ್ಯದ ಒಂದು ತಯಾರಿಕೆ ಏನು ಬಳಸುತ್ತದೆ ಎಂಬುದು. ಅದನ್ನು ನೀವು ಮಾರುವ ಉತ್ಪನ್ನಕ್ಕೆ ಲಿಂಕ್ ಮಾಡಿ ಮತ್ತು ಅದನ್ನು ಸಕ್ರಿಯವಾಗಿ ಹೊಂದಿಸಿ, ಮತ್ತು ಪ್ರತಿ ಮಾರಾಟವು ಪದಾರ್ಥಗಳನ್ನು ತಾನಾಗಿಯೇ ಶೆಲ್ಫ್‌ನಿಂದ ತೆಗೆದುಹಾಕುತ್ತದೆ.",
