  "nav.ledger": "ಲೆಕ್ಕಪತ್ರ ರಫ್ತು",
  "plansLib.businessIncludes.restaurantOps": "ರೆಸ್ಟೋರೆಂಟ್ ಕಾರ್ಯಾಚರಣೆಗಳು — ಮೂರು-ಕಡೆ ಹೊಂದಾಣಿಕೆಯೊಂದಿಗೆ ಪೂರೈಕೆದಾರರ ಇನ್‌ವಾಯ್ಸ್‌ಗಳು, ತ್ಯಾಜ್ಯ ದಾಖಲೆ, ಅವಧಿ ದಿನಾಂಕಗಳು ಮತ್ತು ಅಲರ್ಜಿನ್ ಕೋಷ್ಟಕ",
  "plansLib.businessIncludes.restaurantDaily": "ರೆಸ್ಟೋರೆಂಟ್ ದೈನಂದಿನ ಸಾಧನಗಳು — ತಾಪಮಾನ ದಾಖಲೆಗಳು, ಖಾಲಿಯಾದ ಬೋರ್ಡ್, ತಯಾರಿ ಹಾಳೆಗಳು, ಮೆನು ವಿಶ್ಲೇಷಣೆ, ವ್ಯತ್ಯಾಸ ಮತ್ತು ಲೆಕ್ಕಪತ್ರ ರಫ್ತು",
  "plansLib.businessIncludes.restaurantKitchen": "ರೆಸ್ಟೋರೆಂಟ್, ಅಡುಗೆಮನೆ ಮತ್ತು ಪಾಕವಿಧಾನಗಳು — ಸ್ವಯಂಚಾಲಿತ ಪದಾರ್ಥ ಕಡಿತ ಮತ್ತು ನಿಜವಾದ ಖಾದ್ಯ ವೆಚ್ಚಗಳೊಂದಿಗೆ ಪಾಕವಿಧಾನಗಳು, ತಯಾರಿ ಹಾಳೆಗಳು, ಬ್ಯಾಚ್ ಉತ್ಪಾದನೆ ಮತ್ತು ಮೆನು ವಿಶ್ಲೇಷಣೆ",
  "plansLib.businessIncludes.restaurantStock": "ರೆಸ್ಟೋರೆಂಟ್, ಸ್ಟಾಕ್ ಮತ್ತು ಆರ್ಡರ್‌ಗಳು — ಪಾರ್ ಮಟ್ಟಗಳು, ಪೂರೈಕೆದಾರ ಆರ್ಡರ್ ಮಾರ್ಗದರ್ಶಿ ಮತ್ತು ಸ್ಥಳಗಳ ನಡುವೆ ವರ್ಗಾವಣೆಗಳು, ಜೊತೆಗೆ ಶೆಲ್ಫ್ ಕ್ರಮದಲ್ಲಿ ಎಣಿಕೆ ಹಾಳೆಗಳು",
  "plansLib.businessIncludes.restaurantMoney": "ರೆಸ್ಟೋರೆಂಟ್, ಇನ್‌ವಾಯ್ಸ್‌ಗಳು ಮತ್ತು ಹಣ — ಮೂರು-ಕಡೆ ಹೊಂದಾಣಿಕೆಯೊಂದಿಗೆ ಪೂರೈಕೆದಾರರ ಇನ್‌ವಾಯ್ಸ್‌ಗಳು, ಬೆಲೆ ಎಚ್ಚರಿಕೆಗಳು, ವ್ಯತ್ಯಾಸ ಮತ್ತು ಲೆಕ್ಕಪತ್ರ ರಫ್ತು, ಜೊತೆಗೆ ಪೂರೈಕೆದಾರ ಕ್ರೆಡಿಟ್ ಮೆಮೊಗಳು",
  "plansLib.businessIncludes.restaurantSafety": "ರೆಸ್ಟೋರೆಂಟ್, ಆಹಾರ ಸುರಕ್ಷತೆ — ತಾಪಮಾನ ದಾಖಲೆಗಳು, ಮೊದಲು ಅವಧಿ ಮುಗಿಯುವದು ಮೊದಲು ಕ್ರಮದಲ್ಲಿ ಅವಧಿ ದಿನಾಂಕಗಳು, ದಿನಾಂಕ ಲೇಬಲ್‌ಗಳು ಮತ್ತು ಅಲರ್ಜಿನ್ ಕೋಷ್ಟಕ, ಮತ್ತು ಆಹಾರ ಸುರಕ್ಷತಾ ಫೈಲ್‌ಗಾಗಿ ಭರ್ತಿ ಮಾಡಿದ ತಾಪಮಾನ ಲಾಗ್‌ಗಳು",
  "plansLib.businessIncludes.restaurantFloor": "ರೆಸ್ಟೋರೆಂಟ್, ಹಾಲ್ ಮತ್ತು ಅತಿಥಿಗಳು — ಖಾಲಿಯಾದ ಬೋರ್ಡ್ ಮತ್ತು ತ್ಯಾಜ್ಯ ದಾಖಲೆ",
  "plansLib.businessIncludes.restaurantTeam": "ರೆಸ್ಟೋರೆಂಟ್, ತಂಡ ಮತ್ತು ಸ್ಥಳ — ಸಿಬ್ಬಂದಿ ಊಟಗಳು",
  "inventoryLib.movementStaffMeal": "ಸಿಬ್ಬಂದಿ ಊಟ",
