  "restaurant.doorInvoices": "ಪೂರೈಕೆದಾರರು ಬಿಲ್ ಮಾಡಿದ್ದು, ಖರೀದಿ ಆದೇಶದ ವಿರುದ್ಧ ಪರಿಶೀಲಿಸಿದ್ದು.",
