  "restaurant.doorStaffMeals": "ತಂಡವು ತಿಂದ ಊಟಗಳು, ಸ್ಟಾಕ್ ವಿರುದ್ಧ ಎಣಿಸಿದ್ದು.",
  "restaurant.doorMenu": "ಎಷ್ಟು ಮಾರಾಟವಾಗುತ್ತವೆ ಮತ್ತು ಎಷ್ಟು ಗಳಿಸುತ್ತವೆ ಎಂಬುದರ ಆಧಾರದ ಮೇಲೆ ಶ್ರೇಣೀಕರಿಸಿದ ಖಾದ್ಯಗಳು.",
