  "apiErrors.invoiceFileNotFound": "ಆ ಇನ್‌ವಾಯ್ಸ್ ಫೈಲ್ ದಾಖಲೆಯಲ್ಲಿ ಇಲ್ಲ.",
  "apiErrors.invoiceFileNotGranted": "ಮಾಲೀಕರು, ಅಥವಾ ಪಾಕವಿಧಾನಗಳು ಮತ್ತು ಇನ್‌ವಾಯ್ಸ್‌ಗಳನ್ನು ರಚಿಸಲು ವಿಶ್ವಾಸಾರ್ಹ ತಂಡದ ಸದಸ್ಯರು ಮಾತ್ರ ಇನ್‌ವಾಯ್ಸ್ ಫೈಲ್ ಅನ್ನು ಬದಲಾಯಿಸಬಹುದು.",
