  "apiErrors.restaurantBusinessOnly": "ರೆಸ್ಟೋರೆಂಟ್ ಮೂಲೆ ಬಿಸಿನೆಸ್ ಯೋಜನೆಯ ಭಾಗವಾಗಿದೆ.",
