  "ops.credits.voided": "ಕ್ರೆಡಿಟ್ ಮೆಮೊ ರದ್ದುಮಾಡಲಾಗಿದೆ.",
  "ops.credits.newTitle": "ಹೊಸ ಕ್ರೆಡಿಟ್ ಮೆಮೊ",
