  "apiErrors.ebayNotConfigured": "eBay ಇನ್ನೂ ಕಾನ್ಫಿಗರ್ ಆಗಿಲ್ಲ — ಆ್ಯಪ್ ಮಾಲೀಕರು eBay ಕೀಗಳನ್ನು ಸೇರಿಸಿಲ್ಲ.",
