  "apiErrors.creditMemo.cannotExceedInvoice": "ಕ್ರೆಡಿಟ್ ಮೆಮೊ ಅದು ಕ್ರೆಡಿಟ್ ಮಾಡುವ ಇನ್‌ವಾಯ್ಸ್‌ಗಿಂತ ಹೆಚ್ಚಾಗಿರಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "nav.storefronts": "ಸ್ಟೋರ್‌ಫ್ರಂಟ್ ಸಂಪರ್ಕಗಳು",
  "plansLib.includes.ebaySync": "eBay ಸ್ಟೋರ್‌ಫ್ರಂಟ್ ಸಂಪರ್ಕ — ಮಾರಾಟಗಳು ನಿಮ್ಮ ಸ್ಟಾಕ್ ಅನ್ನು ತಾವಾಗಿಯೇ ನವೀಕರಿಸುತ್ತವೆ",
